async function(vars) {
	var g = new GridWidget(vars.element, vars.credits);
	g.editable = false;
	g.sortable = false;
	g.filterable = false;
	g.pageable = false;
	g.scrollable = false;
	g.groupable = false;
	g.columns = [
		{ field: "Number", title: "[resource_shortdisplayname[Number]]", description: "[resource_description[Number]]"},
		{ field: "DueDate", type: "date", format: "{0:" + type.dateFormat + "}", title: "[resource_shortdisplayname[DueDate]]", description: "[resource_description[DueDate]]"},
		{ field: "TaxPoint", type: "date", format: "{0:" + type.dateFormat + "}", title: "[resource_shortdisplayname[TaxPoint]]", description: "[resource_description[TaxPoint]]"},
		{ field: "DebtorState", template: "#:B2B.transactionStates[DebtorState]#", title: "[resource_shortdisplayname[DebtorState]]", description: "[resource_description[DebtorState]]"},
		{ field: "FundingState", title: "[resource_shortdisplayname[FundingState]]", description: "[resource_description[FundingState]]"},
		{ field: "Value", title: "[resource_shortdisplayname[Value]]", description: "[resource_description[Value]]", format: "{0:" + type.moneyFormat + "}", attributes:{style:"text-align:right;"}},
		{ field: "FundableValue", title: "[resource_shortdisplayname[FundableValue]]", description: "[resource_description[FundableValue]]", format: "{0:" + type.moneyFormat + "}", attributes:{style:"text-align:right;"}}
	];
        var viewResource = "[resource_shortdisplayname[View]]";
        g.commands.push({ name: "view", icon: "k-i-share", text: viewResource, href: "/Transactions/Credit?Id=#:Id#" });
	vars.RelatedCreditsGrid = g;
	return g;
}
